insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('afe11fad-87ef-5344-b1c2-b8cb1d9266ad', 'vi', 'của cô ấy; cô ấy', array['của cô ấy', 'của bà ấy', 'của chị ấy', 'cô ấy']::text[], 'Her vừa là của cô ấy (her name), vừa là cô ấy khi đứng sau động từ (I see her).', '999400659233415aa4ccade0fe02602633266041') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('afe11fad-87ef-5344-b1c2-b8cb1d9266ad', 'en-US', 'belonging to her; also used after a verb, as in I see her', '{}'::text[], 'Her means belonging to her (her name). After a verb it means the woman (I see her).', '999400659233415aa4ccade0fe02602633266041') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
