insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('9058ee25-3576-5993-82c9-fdb8492875f3', 'vi', 'giáo viên, thầy cô', array['giáo viên', 'thầy giáo', 'cô giáo', 'thầy', 'cô']::text[], null, '4a82cb6db537ef6c5b53d144854e146de79502e8') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
