insert into public.lessons (id, unit_id, sort_order, kind) values ('03120364-5438-5176-9a20-304c72d6ef9d', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'introducing-yourself'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('03120364-5438-5176-9a20-304c72d6ef9d', 'vi', 'Ai đấy? Không phải', 'Thêm not sau be để phủ định: is not viết gọn là isn''t, are not viết gọn là aren''t. Hỏi về người dùng Who: Who is that man? Mr. đứng trước họ của đàn ông, Mrs. đứng trước họ của phụ nữ đã có chồng.', 'Isn''t có hai âm tiết, nhấn vào âm đầu: IS-n''t. Aren''t trong tiếng Anh Mỹ chỉ có một âm tiết /ɑrnt/. Đọc rõ âm /t/ cuối của cả hai. Woman đọc /ˈwʊmən/, số nhiều women đọc /ˈwɪmɪn/: chữ o đầu đọc thành âm i. Mr. đọc là mister, Mrs. đọc là missus.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('03120364-5438-5176-9a20-304c72d6ef9d', 'en-US', 'Who is it? No, it isn''t', 'Put not after be to make it negative: is not is isn''t, are not is aren''t. Ask about a person with Who. Use Mr. before a man''s family name and Mrs. before a married woman''s family name.', 'Say the first part of isn''t strongly. Aren''t is one syllable. Say the last /t/ in both. Woman and women sound different: WOO-man, WI-min. Say Mr. as mister and Mrs. as missus.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
