insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('4e4d37d4-3405-52c4-aeed-147bebbc3cd5', 'vi', 'Người đàn ông kia là ai?', array['Ông kia là ai?', 'Người đàn ông đó là ai?', 'Anh kia là ai?']::text[], null, '15ade5135d8f31a35a69ae2c95703caaf944a586') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('130fba0b-b473-5f33-83e8-2403e279d5ab', '03120364-5438-5176-9a20-304c72d6ef9d', 2, 'He''s Mr. Smith, our new teacher.', array['He is Mr. Smith, our new teacher.', 'He''s Mr Smith, our new teacher.', 'He is Mr Smith, our new teacher.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('130fba0b-b473-5f33-83e8-2403e279d5ab', 'vi', 'Đó là thầy Smith, giáo viên mới của chúng tôi.', array['Ông ấy là ông Smith, giáo viên mới của chúng tôi.', 'Anh ấy là thầy Smith, thầy giáo mới của chúng tôi.']::text[], null, 'd1557ae1f3b132423996d92a1e5c23a1b9126ef6') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('327b0ee6-d861-5088-b904-d5a42468b57e', '03120364-5438-5176-9a20-304c72d6ef9d', 3, 'Is that woman Mrs. Smith?', array['Is that woman Mrs Smith?']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('327b0ee6-d861-5088-b904-d5a42468b57e', 'vi', 'Người phụ nữ kia có phải là bà Smith không?', array['Người phụ nữ đó là bà Smith à?', 'Bà kia có phải bà Smith không?']::text[], null, 'd34bb4b116717c0e407f21ff8f726ae15764b87a') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('a6c8dd58-4b5a-5713-b644-11cb2e24d143', '03120364-5438-5176-9a20-304c72d6ef9d', 4, 'No, she isn''t. She''s Anna.', array['No, she is not. She is Anna.', 'No, she isn''t. She is Anna.', 'No, she''s not. She''s Anna.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('a6c8dd58-4b5a-5713-b644-11cb2e24d143', 'vi', 'Không, không phải. Cô ấy là Anna.', array['Không phải. Cô ấy là Anna.', 'Không, cô ấy không phải. Cô ấy là Anna.']::text[], null, 'd522e35405926b1d801cdc12c506ad0ac68a6a72') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
